const pages = [
  page({ file: 'artificial-intelligence.html', section: '01 · AI Foundations', topic: 'Artificial Intelligence', number: '01', back: ['ai-foundations.html', 'AI Foundations'], lede: 'Artificial Intelligence is technology that allows computers to perform tasks that normally require human intelligence.', definition: ['Artificial Intelligence is technology that allows computers to perform tasks that normally require human intelligence.', 'AI is the broad field of creating computer systems that recognize patterns, make predictions, generate content, make recommendations, or take actions. Machine Learning, Deep Learning, and Generative AI are different approaches or areas within AI.'], analogy: 'Think of AI like a student who has studied many examples. When a new problem arrives, it uses learned patterns or written rules to produce a useful result. This is an analogy: AI does not think or understand exactly like a person.', steps: [['Input', 'Receive information', 'A photo, document, message, or sensor reading arrives.'], ['Process', 'Apply rules or patterns', 'The system uses programmed rules or learned patterns.'], ['Decide or generate', 'Create a result', 'It predicts, classifies, recommends, answers, or creates.'], ['Output', 'Return the result', 'The result goes to a person or another system.'], ['Review', 'Check when needed', 'A person verifies important or uncertain results.']], examples: [['Everyday example', 'Photo recognition', 'a photo', 'recognizes visual patterns', 'a face, object, or scene label'], ['Business example', 'Invoice processing', 'an invoice', 'reads fields and flags unusual values', 'structured data and exceptions for review']], not: [['AI ≠ ChatGPT', 'AI: a broad field of computer systems', 'ChatGPT: one AI product'], ['AI ≠ Fixed-rule automation', 'AI: can use learned patterns, predictions, or generation', 'Automation: can simply follow predefined if/then rules'], ['AI ≠ The human mind', 'AI: can perform tasks that appear intelligent', 'The human mind: is not reproduced exactly by AI']], related: ['Artificial Intelligence', '├── Machine Learning', '│   └── Deep Learning', '├── Foundation Models', '└── Generative AI'], chips: [['Machine Learning', 'machine-learning.html'], ['Deep Learning', 'deep-learning.html'], ['Foundation Models', 'foundation-models.html'], ['Generative AI', 'generative-ai.html']], remember: 'AI is the broad field of building computer systems that perform tasks associated with intelligence.', video: ['vedio/artificial-intelligence.mp4', 'vedio/artificial-intelligence.png', 'vedio/artificial-intelligence.vtt', 'A short visual explanation of artificial intelligence.'] }),
  page({ file: 'machine-learning.html', section: '01 · AI Foundations', topic: 'Machine Learning', number: '02', back: ['ai-foundations.html', 'AI Foundations'], lede: 'Machine Learning is a way for computers to learn patterns from examples instead of receiving every rule by hand.', definition: ['Machine Learning is a way for computers to learn patterns from data and use those patterns to make predictions or decisions.', 'During training, an algorithm adjusts model parameters to reduce errors on examples. During use, the trained model applies those learned patterns to new inputs.'], analogy: 'Think of it like learning to sort fruit by seeing many labeled examples. You do not write a rule for every apple; you show examples, and the learner gradually picks up useful patterns.', analogyImage: 'vedio/machine-learning-analogy.png', steps: [['Examples', 'Collect training data', 'The system receives inputs, labels, or useful outcomes.'], ['Learn', 'Adjust model parameters', 'Training changes internal values to reduce error.'], ['Validate', 'Test on new examples', 'A separate set checks whether the pattern generalizes.'], ['Use', 'Make a prediction', 'The trained model produces a result for new input.']], examples: [['Everyday example', 'Spam filtering', 'an incoming email', 'scores patterns learned from labeled messages', 'spam or inbox'], ['Business example', 'Demand forecast', 'sales and calendar data', 'learns relationships from past outcomes', 'a forecast for planning']], not: [['Machine Learning ≠ AI', 'Machine Learning: one approach within the broader AI field', 'AI: the wider field, including rules, learning, and other methods'], ['Machine Learning ≠ Deep Learning', 'Machine Learning: includes many algorithms and model types', 'Deep Learning: a subset that uses multi-layer neural networks'], ['Machine Learning ≠ Fixed-rule programming', 'Machine Learning: learns patterns from examples', 'Fixed rules: people specify the conditions and actions directly']], related: ['Artificial Intelligence', '↓', 'Machine Learning', '↓', 'Training data + model', '↓', 'Prediction or decision'], chips: [['Artificial Intelligence', 'artificial-intelligence.html'], ['Deep Learning', 'deep-learning.html'], ['Foundation Models', 'foundation-models.html'], ['Functional Tests', 'functional-tests.html']], remember: 'Machine Learning learns patterns from examples and applies them to new inputs.', video: ['vedio/machine-learning.mp4', 'vedio/machine-learning.png', 'vedio/machine-learning.vtt', 'A short visual explanation of machine learning.'] }),
  page({ file: 'deep-learning.html', section: '01 · AI Foundations', topic: 'Deep Learning', number: '03', back: ['ai-foundations.html', 'AI Foundations'], lede: 'Deep Learning is Machine Learning that uses neural networks with many layers to learn complex patterns.', definition: ['Deep Learning is a type of Machine Learning that uses neural networks with many layers.', 'The layers transform input into increasingly useful representations. With enough data and compute, deep networks can learn patterns in images, audio, language, and other complex data.'], analogy: 'Think of it like a team of specialists passing a signal along. One layer notices simple shapes or sounds, later layers combine them into richer patterns, and the final layers support a prediction or generation.', analogyImage: 'vedio/deep-learning-analogy.png', steps: [['Input', 'Represent the data', 'Text, pixels, audio, or other input becomes numerical values.'], ['Layers', 'Transform representations', 'Each neural-network layer combines signals from the previous layer.'], ['Train', 'Compare with an objective', 'The model adjusts parameters when its result differs from the target.'], ['Use', 'Apply learned patterns', 'The trained network predicts, classifies, or generates for new input.']], examples: [['Everyday example', 'Speech recognition', 'a spoken sentence', 'processes audio patterns through many layers', 'transcribed text'], ['AI product example', 'Image generation', 'a text prompt', 'uses a deep model to build visual patterns', 'a new image']], not: [['Deep Learning ≠ Machine Learning', 'Deep Learning: one subset of Machine Learning', 'Machine Learning: also includes trees, linear models, and other methods'], ['Deep Learning ≠ Neural Network', 'Deep Learning: usually means a neural network with many layers', 'Neural Network: the broader model family, including shallow networks'], ['Deep Learning ≠ Generative AI', 'Deep Learning: describes how a model is built or trained', 'Generative AI: describes systems that create new content']], related: ['Machine Learning', '↓', 'Neural Network', '↓', 'Many layers', '↓', 'Learned representations'], chips: [['Machine Learning', 'machine-learning.html'], ['Foundation Models', 'foundation-models.html'], ['Generative AI', 'generative-ai.html'], ['Transformer', 'transformer.html']], remember: 'Deep Learning uses many neural-network layers to learn complex representations.', video: ['vedio/deep-learning.mp4', 'vedio/deep-learning.png', 'vedio/deep-learning.vtt', 'A short visual explanation of deep learning.'] }),
  page({ file: 'foundation-models.html', section: '01 · AI Foundations', topic: 'Foundation Models', number: '04', back: ['ai-foundations.html', 'AI Foundations'], lede: 'A Foundation Model is broadly trained on diverse data and can be adapted for many downstream tasks.', definition: ['A Foundation Model is a model trained broadly on large and varied data so it can support many later tasks.', 'It provides a reusable starting point. An application may prompt it, connect tools or retrieval, fine-tune it, or combine it with other software for a specific job.'], analogy: 'Think of it like a well-stocked general workshop. It has many materials and basic skills already available, so a craftsperson can configure it for different projects instead of building every tool from zero.', analogyImage: 'vedio/foundation-models-analogy.png', steps: [['Pre-train', 'Learn broad patterns', 'The model learns from a large and varied training collection.'], ['Represent', 'Build reusable capability', 'Its parameters capture patterns useful across many tasks.'], ['Adapt', 'Add task instructions or data', 'An application narrows the behavior with prompts, tools, retrieval, or fine-tuning.'], ['Deploy', 'Use in a product', 'The adapted system generates or predicts within a defined workflow.']], examples: [['Everyday example', 'Writing helper', 'a request to rewrite a message', 'uses broad language ability plus instructions', 'a clearer draft'], ['Business example', 'Support assistant', 'a customer question and policy context', 'uses a foundation model with retrieval and rules', 'a grounded draft answer']], not: [['Foundation Model ≠ LLM', 'Foundation Model: a broad model category across modalities and tasks', 'LLM: a foundation model specialized for language'], ['Foundation Model ≠ ChatGPT', 'Foundation Model: a model used as a reusable capability', 'ChatGPT: a product that combines models with interface and product systems'], ['Foundation Model ≠ Fine-tuning', 'Foundation Model: the broadly trained starting model', 'Fine-tuning: one possible way to adapt that model']], related: ['Large-scale data', '↓', 'Pre-training', '↓', 'Foundation Model', '↙        ↘', 'Prompt / tools     Fine-tuning', '↓', 'Application'], chips: [['Pre-training', 'pre-training.html'], ['Fine-tuning', 'fine-tuning.html'], ['LLM', 'llm.html'], ['Generative AI', 'generative-ai.html']], remember: 'A Foundation Model is a broadly trained starting point that can support many later tasks.', video: ['vedio/foundation-models.mp4', 'vedio/foundation-models.png', 'vedio/foundation-models.vtt', 'A short visual explanation of foundation models.'] }),
  page({ file: 'generative-ai.html', section: '01 · AI Foundations', topic: 'Generative AI', number: '05', back: ['ai-foundations.html', 'AI Foundations'], lede: 'Generative AI creates new content such as text, images, audio, video, or code from an input or instruction.', definition: ['Generative AI is a class of AI systems that produces new content.', 'The output is generated from patterns learned during training and shaped by the current input, instructions, context, and system controls. Generated content still needs evaluation when accuracy or safety matters.'], analogy: 'Think of it like a musician who has studied many songs and can compose a new piece from a brief. The new piece is not a copied recording, but it is shaped by learned patterns and the direction you give.', analogyImage: 'vedio/generative-ai-analogy.png', steps: [['Input', 'Provide a prompt or source', 'A user gives text, an image, audio, code, or other context.'], ['Represent', 'Turn input into model units', 'The system converts the request into a form the model can process.'], ['Generate', 'Predict or construct content', 'The model produces output step by step or through iterative refinement.'], ['Check', 'Review the result', 'A person or system checks quality, policy, format, and factual support.']], examples: [['Everyday example', 'Image creation', 'a text description of a room', 'generates visual content from learned patterns', 'a new image'], ['Business example', 'Drafting a report', 'notes and a report outline', 'generates a first draft in a chosen format', 'a reviewable report draft']], not: [['Generative AI ≠ AI', 'Generative AI: one area focused on creating content', 'AI: the broader field, including prediction, classification, and control'], ['Generative AI ≠ Search', 'Generative AI: constructs a new response', 'Search: retrieves existing documents or pages'], ['Generative AI ≠ Human creativity', 'Generative AI: recombines learned patterns under an input', 'Human creativity: includes human goals, experience, judgment, and responsibility']], related: ['Generative AI', '├── Text generation', '├── Image generation', '├── Audio generation', '└── Video generation', 'Often powered by Foundation Models'], chips: [['Artificial Intelligence', 'artificial-intelligence.html'], ['Foundation Models', 'foundation-models.html'], ['LLM', 'llm.html'], ['RAG', 'rag.html']], remember: 'Generative AI creates new content from learned patterns and current instructions.', video: ['vedio/generative-ai.mp4', 'vedio/generative-ai.png', 'vedio/generative-ai.vtt', 'A short visual explanation of generative AI.'] }),

  page({ file: 'llm.html', section: '02 · LLMs & Transformers', topic: 'LLM', number: '01', back: ['llms-transformers.html', 'LLMs & Transformers'], lede: 'An LLM is a language model trained to predict and generate text from tokens.', definition: ['A Large Language Model is a model that learns patterns in language and uses them to predict likely next tokens.', 'It can summarize, translate, answer, classify, or generate text, but it does not automatically know that an output is true. Its behavior depends on training, context, instructions, tools, and evaluation.'], analogy: 'Think of it like an extremely well-read autocomplete system. It has learned many patterns in language, but it still needs the right context and checks when the answer matters.', analogyImage: 'vedio/llm-analogy.png', steps: [['Input', 'Read tokens', 'The prompt and available context are converted into tokens.'], ['Process', 'Use the Transformer', 'Attention and neural-network layers process relationships between tokens.'], ['Predict', 'Score possible next tokens', 'The model estimates which continuations fit the context.'], ['Repeat', 'Generate a response', 'Selected tokens are added one by one until the system stops.']], examples: [['Everyday example', 'Message rewrite', 'a rough sentence', 'predicts a clearer continuation in a chosen tone', 'a revised sentence'], ['Business example', 'Support summary', 'a customer conversation', 'processes the supplied context and instructions', 'a concise summary with open issues']], not: [['LLM ≠ ChatGPT', 'LLM: a type of language model', 'ChatGPT: a product that uses models plus interface and other systems'], ['LLM ≠ AI', 'LLM: one model type', 'AI: the broader field of intelligent computer systems'], ['LLM ≠ Search Engine', 'LLM: generates text from learned patterns and current context', 'Search engine: retrieves existing information from an index']], related: ['Text', '↓', 'Tokens', '↓', 'Transformer', '↓', 'LLM inference', '↓', 'Generated text'], chips: [['Transformer', 'transformer.html'], ['Token', 'token.html'], ['Context Window', 'context-window.html'], ['RAG', 'rag.html'], ['Fine-tuning', 'fine-tuning.html']], remember: 'An LLM predicts and generates language one token at a time from context.', video: ['vedio/llm.mp4', 'vedio/llm.png', '', 'A short visual explanation of large language models.'] }),
  page({ file: 'transformer.html', section: '02 · LLMs & Transformers', topic: 'Transformer', number: '02', back: ['llms-transformers.html', 'LLMs & Transformers'], lede: 'A Transformer is a neural-network architecture that processes relationships between tokens.', definition: ['A Transformer is a neural-network architecture that processes relationships between tokens.', 'Its attention mechanism lets the model weigh which parts of the input are useful when producing each representation or output token.'], analogy: 'Think of it like a reading group where every word can look around the table and decide which other words matter for the current task.', analogyImage: 'vedio/transformer-analogy.png', steps: [['Tokens', 'Split the input', 'Text becomes token IDs and numerical vectors.'], ['Attention', 'Compare context', 'Each position weighs information from relevant positions.'], ['Layers', 'Transform representations', 'Repeated attention and feed-forward layers refine the signal.'], ['Output', 'Score possible results', 'A final layer scores next tokens or task labels.'], ['Decode', 'Produce the result', 'The system selects output tokens or another task result.']], examples: [['Everyday example', 'Pronoun resolution', 'a sentence with “it” or “they”', 'weighs nearby words and references', 'a more likely continuation'], ['AI product example', 'Translation', 'a sentence in one language', 'maps relationships across tokens', 'translated text']], not: [['Transformer ≠ LLM', 'Transformer: an architecture', 'LLM: a language model often built with that architecture'], ['Transformer ≠ Attention', 'Transformer: a full architecture with several components', 'Attention: one important mechanism inside it'], ['Transformer ≠ ChatGPT', 'Transformer: a model architecture', 'ChatGPT: a product that may use Transformer-based models plus other systems']], related: ['Tokens', '↓', 'Embeddings', '↓', 'Attention + layers', '↓', 'Output scores'], chips: [['LLM', 'llm.html'], ['Token', 'token.html'], ['Parameters', 'parameters.html'], ['Pre-training', 'pre-training.html'], ['KV Cache', 'kv-cache.html']], remember: 'A Transformer uses attention and stacked neural-network layers to process relationships between tokens.', video: ['vedio/transformer.mp4', 'vedio/transformer.png', '', 'A short visual explanation of Transformers.'] }),
  page({ file: 'parameters.html', section: '02 · LLMs & Transformers', topic: 'Parameters', number: '03', back: ['llms-transformers.html', 'LLMs & Transformers'], lede: 'Parameters are the learned numerical values inside a model.', definition: ['Parameters are numerical values that a model adjusts during training.', 'Together, they shape how the model transforms input and scores possible outputs. A parameter count describes scale, but it does not by itself guarantee quality, truthfulness, or speed.'], analogy: 'Think of parameters like the settings inside a large mixing desk. Training adjusts many tiny controls so the system responds differently to different patterns.', analogyImage: 'vedio/parameters-analogy.png', steps: [['Initialize', 'Start with values', 'The model begins with values that do not yet encode the target skill.'], ['Train', 'Compare predictions with targets', 'The system measures error on many examples.'], ['Update', 'Adjust the values', 'Optimization changes parameters to reduce future error.'], ['Use', 'Apply the learned settings', 'The trained model uses its parameters on new inputs.']], examples: [['Everyday example', 'Next-word prediction', '“The weather is”', 'uses learned values to score continuations', 'a ranked set of next tokens'], ['Business example', 'Ticket routing', 'a support ticket', 'uses learned values to score categories', 'a predicted route or queue']], not: [['Parameters ≠ Training data', 'Parameters: learned numerical values in the model', 'Training data: examples used to adjust those values'], ['Parameters ≠ Model size on disk', 'Parameters: count of learned values', 'File size: also depends on numeric precision, format, and metadata'], ['Parameters ≠ Quality', 'Parameters: one measure of model scale', 'Quality: depends on data, training, architecture, evaluation, and task fit']], related: ['Training data', '↓', 'Optimization', '↓', 'Parameters', '↓', 'Model behavior'], chips: [['Transformer', 'transformer.html'], ['Pre-training', 'pre-training.html'], ['Fine-tuning', 'fine-tuning.html'], ['Quantization', 'quantization.html']], remember: 'Parameters are the learned numerical values that shape a model’s behavior.', video: ['vedio/parameters.mp4', 'vedio/parameters.png', '', 'A short visual explanation of model parameters.'] }),
  page({ file: 'pre-training.html', section: '02 · LLMs & Transformers', topic: 'Pre-training', number: '04', back: ['llms-transformers.html', 'LLMs & Transformers'], lede: 'Pre-training is the broad training stage where a model learns general patterns from a large dataset.', definition: ['Pre-training is the initial, broad training stage for a model.', 'For a language model, this often means learning to predict missing or next tokens across a large collection of text. The result is a base model that can later be instructed, fine-tuned, or connected to external information.'], analogy: 'Think of it like general education before job training. A person studies many subjects first; later, a focused course can teach a narrower role.', analogyImage: 'vedio/pre-training-analogy.png', steps: [['Collect', 'Prepare broad data', 'The training pipeline selects, filters, and tokenizes a large dataset.'], ['Predict', 'Learn from an objective', 'The model predicts tokens or another training target.'], ['Update', 'Adjust parameters', 'Optimization changes the model after each batch of examples.'], ['Finish', 'Save a base model', 'The trained model becomes a reusable starting point for later adaptation.']], examples: [['Everyday example', 'Language completion', 'a partial sentence', 'learns from many examples of what tends to follow', 'a likely continuation'], ['Business example', 'General assistant base', 'broad language data', 'learns general language patterns before product instructions', 'a base model ready for adaptation']], not: [['Pre-training ≠ Fine-tuning', 'Pre-training: broad learning before a specific product task', 'Fine-tuning: later training on narrower data or behavior'], ['Pre-training ≠ Prompting', 'Pre-training: changes model parameters', 'Prompting: supplies instructions at use time'], ['Pre-training ≠ Memorizing a database', 'Pre-training: learns statistical patterns from data', 'A database: stores retrievable records with explicit lookup behavior']], related: ['Broad data', '↓', 'Pre-training objective', '↓', 'Base model', '↙       ↘', 'Prompting   Fine-tuning'], chips: [['Foundation Models', 'foundation-models.html'], ['Parameters', 'parameters.html'], ['Fine-tuning', 'fine-tuning.html'], ['LLM', 'llm.html']], remember: 'Pre-training gives a model broad capability before a specific application adapts it.', video: ['vedio/pre-training.mp4', 'vedio/pre-training.png', '', 'A short visual explanation of pre-training.'] }),
  page({ file: 'fine-tuning.html', section: '02 · LLMs & Transformers', topic: 'Fine-tuning', number: '05', back: ['llms-transformers.html', 'LLMs & Transformers'], lede: 'Fine-tuning is additional training that adapts a pre-trained model for a narrower task, style, or behavior.', definition: ['Fine-tuning updates some or all model parameters using a focused dataset after pre-training.', 'It can make a model more consistent for a task, format, domain, or style. It does not automatically add a reliable, up-to-date knowledge source, and it can reduce general behavior if done poorly.'], analogy: 'Think of it like giving someone specialized training after general education. They keep broad skills but practice a narrower job with examples from that job.', analogyImage: 'vedio/fine-tuning-analogy.png', steps: [['Start', 'Choose a base model', 'A broadly trained model provides general capability.'], ['Prepare', 'Create focused examples', 'Examples show the desired inputs, outputs, format, or behavior.'], ['Train', 'Update parameters', 'The model learns from the focused dataset.'], ['Evaluate', 'Check the trade-offs', 'Tests confirm whether the target behavior improved without harmful regressions.']], examples: [['Everyday example', 'Consistent tone', 'a draft message', 'uses examples of a preferred writing style', 'a more consistent rewrite'], ['Business example', 'Structured extraction', 'an invoice image or text', 'learns a domain-specific output format from examples', 'fields in a predictable schema']], not: [['Fine-tuning ≠ RAG', 'Fine-tuning: changes model behavior through additional training', 'RAG: retrieves external information at query time'], ['Fine-tuning ≠ Prompting', 'Fine-tuning: changes parameters', 'Prompting: changes the input instructions without retraining'], ['Fine-tuning ≠ Updating a live database', 'Fine-tuning: creates a new model version from training examples', 'A database update: changes records that a system can retrieve']], related: ['Base model', '↓', 'Focused examples', '↓', 'Fine-tuning', '↓', 'Specialized behavior'], chips: [['Pre-training', 'pre-training.html'], ['Foundation Models', 'foundation-models.html'], ['RAG', 'rag.html'], ['Structured Outputs', 'structured-outputs.html']], remember: 'Fine-tuning adapts a pre-trained model’s behavior; it is not a live knowledge update.', video: ['vedio/fine-tuning.mp4', 'vedio/fine-tuning.png', '', 'A short visual explanation of fine-tuning.'] }),

  page({ file: 'token.html', section: '03 · Tokens, Context & Inference', topic: 'Token', number: '01', back: ['tokens-context-inference.html', 'Tokens, Context & Inference'], lede: 'A token is a small unit of text that an AI model reads and processes.', definition: ['A token is a small unit of text that an AI model reads and processes.', 'A token may be a whole word, part of a word, punctuation, or another text unit depending on the tokenizer. Token counts affect context limits, input cost, and generation speed.'], analogy: 'Think of it like cutting a sentence into small LEGO pieces. The model processes these pieces rather than reading the whole sentence exactly the way a person sees words.', analogyImage: 'vedio/token-lego-analogy.png', steps: [['Text', 'Receive a string', 'The system starts with human-readable text.'], ['Tokenizer', 'Split into pieces', 'A tokenizer maps the text into model-specific token units.'], ['IDs', 'Convert pieces to numbers', 'Each token becomes an ID the model can process.'], ['Model', 'Use the token sequence', 'The model reads the sequence as part of its context.']], examples: [['Everyday example', 'Short sentence', '“ChatGPT is useful.”', 'splits text into several tokens', 'a token sequence for the model'], ['Business example', 'Document cost', 'a long policy', 'counts tokens before sending the request', 'a context and cost estimate']], not: [['Token ≠ Word', 'Token: a model-specific unit of text', 'Word: a human language unit that may be one or many tokens'], ['Token ≠ Character', 'Token: may contain several characters or part of a word', 'Character: one letter, number, symbol, or code point'], ['Token ≠ Meaning', 'Token: an input unit used by the model', 'Meaning: comes from patterns across many tokens and context']], related: ['Text', '↓', 'Tokenizer', '↓', 'Tokens', '↓', 'Context Window', '↓', 'LLM inference'], chips: [['Context Window', 'context-window.html'], ['LLM', 'llm.html'], ['KV Cache', 'kv-cache.html'], ['Tokens per Second', 'tokens-per-second.html']], remember: 'AI models process tokens, not text exactly the way humans see words.', video: ['vedio/token.mp4', 'vedio/token.png', '', 'A short visual explanation of tokens.'] }),
  page({ file: 'context-window.html', section: '03 · Tokens, Context & Inference', topic: 'Context Window', number: '02', back: ['tokens-context-inference.html', 'Tokens, Context & Inference'], lede: 'A context window is the amount of tokenized information a model can use in one request.', definition: ['A context window is the maximum amount of tokenized input and output that a model can handle for one operation.', 'It may include system instructions, conversation history, retrieved documents, tool results, and the new answer. A larger context window does not guarantee that every detail will receive equal attention.'], analogy: 'Think of it like the size of a working desk. You can use the papers on the desk together; when the desk is full, something must be removed, summarized, or moved to storage.', analogyImage: 'vedio/context-window-analogy.png', steps: [['Collect', 'Gather request context', 'Instructions, history, documents, and the new question are assembled.'], ['Tokenize', 'Count the units', 'The system converts all content into tokens.'], ['Fit', 'Check the limit', 'The request must fit within the model’s input and output budget.'], ['Generate', 'Use the available context', 'The model produces an answer from the information in the current window.']], examples: [['Everyday example', 'Long conversation', 'many earlier messages', 'keeps selected history in the current window', 'a response using the visible context'], ['Business example', 'Policy assistant', 'a question plus policy excerpts', 'fits only the relevant sections', 'an answer based on the supplied context']], not: [['Context Window ≠ Memory', 'Context Window: information available for the current model operation', 'Memory: information stored or retrieved across interactions'], ['Context Window ≠ Model knowledge', 'Context Window: current input and generated output budget', 'Model knowledge: patterns learned during training'], ['Context Window ≠ File storage', 'Context Window: temporary working space for a request', 'File storage: persistent data that must be retrieved or supplied']], related: ['Instructions + history', '+', 'Retrieved documents', '↓', 'Context Window', '↓', 'Inference'], chips: [['Token', 'token.html'], ['KV Cache', 'kv-cache.html'], ['RAG', 'rag.html'], ['Latency', 'latency.html']], remember: 'The context window is the model’s working space for one operation, not a permanent memory.', video: ['vedio/context-window.mp4', 'vedio/context-window.png', '', 'A short visual explanation of context windows.'] }),
  page({ file: 'kv-cache.html', section: '03 · Tokens, Context & Inference', topic: 'KV Cache', number: '03', back: ['tokens-context-inference.html', 'Tokens, Context & Inference'], lede: 'A KV cache stores intermediate attention information so a model can reuse earlier work during generation.', definition: ['A KV cache is a runtime cache of key and value tensors computed for tokens that have already been processed.', 'During autoregressive generation, the model can reuse these tensors instead of recomputing attention for the same earlier tokens. The cache improves speed, but it uses memory and grows with context length.'], analogy: 'Think of it like keeping notes from work already done. When you continue a long calculation, you reuse the notes instead of starting the same calculation again.', analogyImage: 'vedio/kv-cache-analogy.png', steps: [['Read', 'Process the prompt', 'The model computes attention information for the input tokens.'], ['Cache', 'Store key and value tensors', 'The runtime keeps reusable intermediate results.'], ['Generate', 'Add one output token', 'The new token is processed against the cached earlier context.'], ['Reuse', 'Continue without repeating', 'Earlier attention work is reused for the next token.']], examples: [['Everyday example', 'Long reply', 'a prompt with a long history', 'keeps earlier attention results nearby', 'faster continuation than full recomputation'], ['AI product example', 'Chat service', 'a multi-turn conversation', 'allocates cache memory for active requests', 'better decode throughput within memory limits']], not: [['KV Cache ≠ Context Window', 'KV Cache: stored intermediate computation for reuse', 'Context Window: the amount of tokenized information allowed'], ['KV Cache ≠ Long-term Memory', 'KV Cache: temporary runtime state for an active request', 'Long-term Memory: data stored for later retrieval'], ['KV Cache ≠ Model Parameters', 'KV Cache: request-specific tensors', 'Parameters: learned values shared by the model version']], related: ['Prompt tokens', '↓', 'Attention computation', '↓', 'KV Cache', '↓', 'Next-token generation'], chips: [['Context Window', 'context-window.html'], ['Token', 'token.html'], ['Latency', 'latency.html'], ['Tokens per Second', 'tokens-per-second.html']], remember: 'KV Cache speeds repeated attention work during generation, but it consumes memory.', video: ['vedio/kv-cache.mp4', 'vedio/kv-cache.png', '', 'A short visual explanation of KV cache.'] }),
  page({ file: 'latency.html', section: '03 · Tokens, Context & Inference', topic: 'Latency', number: '04', back: ['tokens-context-inference.html', 'Tokens, Context & Inference'], lede: 'Latency is the time a user or system waits for an AI response or response stage.', definition: ['Latency is the elapsed time between an event and the result you are measuring.', 'For an AI request, teams may measure time to first token, time to first useful result, or total response time. These measures answer different user-experience questions.'], analogy: 'Think of it like waiting at a café. Time until someone acknowledges your order is different from time until the full drink is ready.', analogyImage: 'vedio/latency-analogy.png', steps: [['Request', 'Send the input', 'The user or system starts an AI operation.'], ['Queue', 'Wait for capacity', 'The request may wait for a worker, GPU, or network connection.'], ['Prefill', 'Process the input', 'The system reads the prompt and context.'], ['First result', 'Measure first response', 'Time to first token or first useful output becomes visible.'], ['Complete', 'Measure total time', 'The full response finishes and can be used.']], examples: [['Everyday example', 'Chat reply', 'a short question', 'measures time until the answer starts', 'a fast or slow first response'], ['Business example', 'Document workflow', 'an uploaded invoice', 'measures processing time to a validated result', 'a completed record or exception']], not: [['Latency ≠ Tokens per Second', 'Latency: time spent waiting for a stage or result', 'Tokens per Second: output generation throughput'], ['Latency ≠ Context Window', 'Latency: a time measurement', 'Context Window: a token capacity'], ['Latency ≠ Quality', 'Latency: how quickly a result arrives', 'Quality: how correct or useful the result is']], related: ['Request', '↓', 'Queue + prefill', '↓', 'Time to first token', '↓', 'Decode', '↓', 'Total latency'], chips: [['Tokens per Second', 'tokens-per-second.html'], ['Context Window', 'context-window.html'], ['KV Cache', 'kv-cache.html'], ['Runtime Constraints', 'runtime-constraints.html']], remember: 'Latency measures waiting time; define which response milestone you are measuring.', video: ['vedio/latency.mp4', 'vedio/latency.png', '', 'A short visual explanation of AI latency.'] }),
  page({ file: 'tokens-per-second.html', section: '03 · Tokens, Context & Inference', topic: 'Tokens per Second', number: '05', back: ['tokens-context-inference.html', 'Tokens, Context & Inference'], lede: 'Tokens per second measures how quickly a model generates output tokens during decoding.', definition: ['Tokens per second is a throughput measure for generated tokens over time.', 'It is usually measured after generation starts. It does not include every part of the user experience, such as queueing or time to first token, and it depends on model, hardware, context, and settings.'], analogy: 'Think of it like the speed of writing after the first word has appeared. A fast writing rate is useful, but it does not tell you how long you waited before the writer began.', analogyImage: 'vedio/tokens-per-second-analogy.png', steps: [['Prompt', 'Send the request', 'The system receives input and prepares the context.'], ['Prefill', 'Process input tokens', 'The model reads the prompt before generating output.'], ['Decode', 'Generate output tokens', 'The model predicts and emits tokens one by one.'], ['Measure', 'Count output over time', 'The benchmark reports a rate under stated conditions.']], examples: [['Everyday example', 'Chat reply', 'a short prompt', 'generates 40 output tokens at 20 tokens per second', 'about two seconds of decode time'], ['Business example', 'Batch summaries', 'many documents', 'measures output throughput under load', 'capacity for a target queue']], not: [['Tokens per Second ≠ Latency', 'Tokens per Second: generation throughput', 'Latency: time to first or complete result'], ['Tokens per Second ≠ Token count', 'Tokens per Second: tokens generated per unit time', 'Token count: how many units are generated'], ['Tokens per Second ≠ Quality', 'Tokens per Second: a performance metric', 'Quality: a separate measure of correctness or usefulness']], related: ['Prompt', '↓', 'Prefill', '↓', 'Decode tokens', '↓', 'Tokens per second'], chips: [['Latency', 'latency.html'], ['Token', 'token.html'], ['KV Cache', 'kv-cache.html'], ['Quantization', 'quantization.html']], remember: 'Tokens per second is output throughput, not a complete measure of user experience.', video: ['vedio/tokens-per-second.mp4', 'vedio/tokens-per-second.png', '', 'A short visual explanation of tokens per second.'] }),

  page({ file: 'system-prompts.html', section: '04 · Prompting & System Design', topic: 'System Prompt', number: '01', back: ['prompting-system-design.html', 'Prompting & System Design'], lede: 'A system prompt is application-provided instruction context that sets an AI system’s role, rules, and boundaries.', definition: ['A system prompt is instruction context supplied by the application, usually before the user’s message.', 'It can define the task, important terms, decision rules, tool behavior, output requirements, and failure path. It guides the model, but permissions and validation still belong in software around it.'], analogy: 'Think of it like a job brief handed to a new front-desk teammate. It explains the role, house rules, and when to call a supervisor, but it does not unlock doors or approve refunds by itself.', analogyImage: 'vedio/system-prompts-analogy.png', steps: [['Role', 'State the job', 'Explain what the system is responsible for.'], ['Rules', 'Set priorities and limits', 'Describe what it must do, avoid, or ask about.'], ['Tools', 'Define allowed actions', 'Explain when a tool may be used and what inputs it needs.'], ['Output', 'Specify the result shape', 'State the required format and fields.'], ['Failure', 'Define the safe exit', 'Say when to abstain, ask, retry, or hand off.']], examples: [['Everyday example', 'Writing helper', 'a request to rewrite a message', 'applies tone and length instructions', 'a draft with the requested style'], ['Business example', 'Support drafting', 'a customer question and policy excerpt', 'uses only supplied evidence and flags uncertainty', 'a draft plus review fields']], not: [['System Prompt ≠ Application Code', 'System Prompt: instructions that guide model behavior', 'Application code: enforces permissions, validation, and business rules'], ['System Prompt ≠ User Prompt', 'System Prompt: product-level instructions and boundaries', 'User Prompt: the current user request'], ['System Prompt ≠ Security Boundary', 'System Prompt: can state a safety rule', 'Security boundary: must be enforced by access controls and trusted code']], related: ['Application', '↓', 'System Prompt', '↓', 'User input + tools', '↓', 'Validated output'], chips: [['Structured Outputs', 'structured-outputs.html'], ['Failure Handling', 'failure-handling.html'], ['Tool Calling', 'tool-calling.html'], ['Agent Loop', 'agent-loop.html']], remember: 'A system prompt is a behavior brief, not a substitute for permissions or validation.', video: ['vedio/system-prompts.mp4', 'vedio/system-prompts.png', 'vedio/system-prompts.vtt', 'A visual explanation of system prompts.'] }),
  page({ file: 'structured-outputs.html', section: '04 · Prompting & System Design', topic: 'Structured Outputs', number: '02', back: ['prompting-system-design.html', 'Prompting & System Design'], lede: 'Structured output means asking an AI system to return data in a defined shape that software can check and use.', definition: ['Structured output is a response that follows a specified schema, such as JSON fields with known types.', 'A schema makes the interface easier to validate and integrate, but a well-formed response can still contain wrong or unsupported values.'], analogy: 'Think of it like a form with labeled boxes. The form makes the answer easier to process, but someone still has to check whether the information in each box is correct.', analogyImage: 'vedio/structured-outputs-analogy.png', steps: [['Define', 'Choose a schema', 'Name the fields, types, allowed values, and required fields.'], ['Prompt', 'Explain the expected shape', 'The model receives the task and output contract.'], ['Generate', 'Return structured data', 'The system produces values in the requested format.'], ['Validate', 'Check syntax and meaning', 'Software verifies the shape, values, evidence, and business rules.'], ['Recover', 'Handle invalid results', 'The application retries, repairs, or escalates when needed.']], examples: [['Everyday example', 'Trip plan', 'a request for three activities', 'returns an array with name, time, and location', 'data that a calendar UI can display'], ['Business example', 'Invoice extraction', 'an invoice document', 'returns vendor, date, total, and review flag', 'validated fields for a workflow']], not: [['Structured Outputs ≠ Correct Outputs', 'Structured Outputs: a predictable response shape', 'Correct Outputs: values that are accurate and supported'], ['Structured Outputs ≠ Plain Text', 'Structured Outputs: fields have a defined contract', 'Plain Text: flexible content without a machine-checked shape'], ['Structured Outputs ≠ Database Schema', 'Structured Outputs: a response interface at one system boundary', 'Database schema: persistent storage design with its own constraints']], related: ['Task', '↓', 'Output schema', '↓', 'Model response', '↓', 'Validation', '↓', 'Downstream system'], chips: [['System Prompt', 'system-prompts.html'], ['Failure Handling', 'failure-handling.html'], ['Functional Tests', 'functional-tests.html'], ['Grounding', 'grounding.html']], remember: 'A structured response is easier to validate, but structure alone does not make content correct.', video: ['vedio/structured-outputs.mp4', 'vedio/structured-outputs.png', 'vedio/structured-outputs.vtt', 'A visual explanation of structured outputs.'] }),
  page({ file: 'failure-handling.html', section: '04 · Prompting & System Design', topic: 'Failure Handling', number: '03', back: ['prompting-system-design.html', 'Prompting & System Design'], lede: 'Failure handling defines what an AI system does when input, tools, evidence, or model output is incomplete or wrong.', definition: ['Failure handling is the set of checks and recovery paths used when an AI workflow cannot safely complete a request.', 'A reliable system can detect invalid output, missing evidence, timeouts, permission errors, and low confidence. It can then retry, ask for clarification, return a bounded answer, or hand off to a person.'], analogy: 'Think of it like a train system with signals and alternate routes. A delay or blocked track should trigger a known response instead of making the train continue blindly.', analogyImage: 'vedio/failure-handling-analogy.png', steps: [['Detect', 'Notice the failure', 'Validate input, output, evidence, tool result, and timing.'], ['Classify', 'Identify the failure type', 'Separate retryable, user-fixable, and unsafe cases.'], ['Recover', 'Choose the next action', 'Retry, repair, ask, use a fallback, or stop.'], ['Escalate', 'Keep a human path', 'Route important or uncertain cases for review.']], examples: [['Everyday example', 'Missing detail', '“Book a table tomorrow”', 'asks which city and time are missing', 'a clarification question'], ['Business example', 'Policy gap', 'a request outside the supplied policy', 'states the gap and routes for review', 'a bounded response with escalation']], not: [['Failure Handling ≠ Retry Everything', 'Failure Handling: chooses a response based on failure type', 'Blind retrying: repeats the same action without new information'], ['Failure Handling ≠ Refusal Only', 'Failure Handling: includes recovery, clarification, fallback, and handoff', 'Refusal: one possible safe outcome'], ['Failure Handling ≠ Error Logging', 'Failure Handling: changes what the workflow does next', 'Logging: records what happened for diagnosis']], related: ['Input validation', '↓', 'Model or tool result', '↓', 'Failure classification', '↙        ↘', 'Retry / clarify     Stop / hand off'], chips: [['System Prompt', 'system-prompts.html'], ['Structured Outputs', 'structured-outputs.html'], ['Agent Loop', 'agent-loop.html'], ['Functional Tests', 'functional-tests.html']], remember: 'A reliable AI system needs an explicit safe path for uncertainty and failure.', video: ['vedio/failure-handling.mp4', 'vedio/failure-handling.png', 'vedio/failure-handling.vtt', 'A visual explanation of failure handling.'] }),

  page({ file: 'embeddings.html', section: '05 · Embeddings, RAG & Vector Search', topic: 'Embeddings', number: '01', back: ['embeddings-rag-vector-search.html', 'Embeddings, RAG & Vector Search'], lede: 'An embedding is a numerical representation that places content in a space where useful similarities can be compared.', definition: ['An embedding is a vector of numbers produced by an embedding model for text, images, audio, or other data.', 'Content with related patterns may be placed closer together in that vector space. The vector is a representation for comparison or retrieval; it is not a complete answer by itself.'], analogy: 'Think of it like putting every idea on a map of meaning. Similar ideas tend to be placed in nearby neighborhoods, even when they use different words.', analogyImage: 'vedio/embeddings-analogy.png', steps: [['Input', 'Provide content', 'A document chunk, query, image, or other item enters the system.'], ['Embed', 'Map it to a vector', 'An embedding model converts the item into numerical coordinates.'], ['Compare', 'Measure similarity', 'The system compares vectors with a distance or similarity function.'], ['Retrieve', 'Use nearby items', 'A search or ranking step returns useful candidates for the application.']], examples: [['Everyday example', 'Policy question', '“Can I cancel after the vessel sails?”', 'embeds the query and policy chunks', 'a nearby chunk about post-departure cancellation'], ['Business example', 'Knowledge search', 'a support question', 'finds semantically related internal documents', 'ranked evidence for an assistant']], not: [['Embedding ≠ Token', 'Embedding: a numerical representation of an input', 'Token: a unit processed by a model'], ['Embedding ≠ Vector Database', 'Embedding: the vector representation', 'Vector Database: a system that stores and searches vectors'], ['Embedding ≠ Answer', 'Embedding: a signal for similarity', 'Answer: generated or selected content that still needs checking']], related: ['Text or image', '↓', 'Embedding model', '↓', 'Vector', '↓', 'Similarity comparison', '↓', 'Retrieval'], chips: [['RAG', 'rag.html'], ['Vector Search', 'vector-search.html'], ['Grounding', 'grounding.html'], ['Token', 'token.html']], remember: 'Embeddings turn content into vectors so semantic similarity can be searched.', video: ['vedio/embeddings.mp4', 'vedio/embeddings.png', '', 'A visual explanation of embeddings.'] }),
  page({ file: 'rag.html', section: '05 · Embeddings, RAG & Vector Search', topic: 'RAG', number: '02', back: ['embeddings-rag-vector-search.html', 'Embeddings, RAG & Vector Search'], lede: 'RAG lets an AI system retrieve relevant information before generating an answer.', definition: ['Retrieval-Augmented Generation combines information retrieval with model generation.', 'A RAG system finds relevant content at query time, adds selected evidence to the model’s context, and asks the model to generate an answer from that context.'], analogy: 'Think of it like taking an exam with an open book. The model is not limited to what it learned earlier; before answering, it can look up relevant pages.', analogyImage: 'vedio/rag-analogy.png', steps: [['Question', 'Receive the request', 'The system receives a question and any filters or permissions.'], ['Search', 'Find relevant content', 'The query is embedded or otherwise used to retrieve candidate chunks.'], ['Select', 'Build evidence context', 'The system ranks, filters, and formats the useful sources.'], ['Generate', 'Ask the model to answer', 'The model uses the selected evidence and instructions.'], ['Check', 'Cite or verify', 'The application checks support, access, and answer quality.']], examples: [['Everyday example', 'Holiday policy', '“How many annual leave days do employees receive?”', 'searches the current HR policy and supplies the relevant passage', 'an answer based on the current policy'], ['Business example', 'Operations assistant', 'a question about a settlement rule', 'retrieves the current policy with source metadata', 'a grounded answer or review flag']], not: [['RAG ≠ Fine-tuning', 'RAG: retrieves external information at query time', 'Fine-tuning: changes model behavior through additional training'], ['RAG ≠ Search Engine', 'RAG: combines retrieval with generation and application controls', 'Search: retrieves or ranks existing information'], ['RAG ≠ Guaranteed Truth', 'RAG: gives the model selected evidence', 'Truth: still depends on source quality, retrieval, reasoning, and checks']], related: ['Question', '↓', 'Embedding', '↓', 'Vector search', '↓', 'Retrieval', '↓', 'LLM', '↓', 'Answer'], chips: [['Embeddings', 'embeddings.html'], ['Vector Search', 'vector-search.html'], ['Grounding', 'grounding.html'], ['LLM', 'llm.html']], remember: 'RAG lets an AI retrieve relevant information before generating an answer.', video: ['vedio/rag.mp4', 'vedio/rag.png', '', 'A visual explanation of retrieval-augmented generation.'] }),
  page({ file: 'vector-search.html', section: '05 · Embeddings, RAG & Vector Search', topic: 'Vector Search', number: '03', back: ['embeddings-rag-vector-search.html', 'Embeddings, RAG & Vector Search'], lede: 'Vector search finds items whose embeddings are close to a query embedding.', definition: ['Vector search compares numerical vectors to find content that is similar in the chosen representation space.', 'It is useful when related content may use different words. Practical systems often combine vector similarity with keyword search, metadata filters, permissions, and reranking.'], analogy: 'Think of it like a library organized by meaning instead of alphabetically. A question about changing a booking can sit near documents about amendments, even if the wording is different.', analogyImage: 'vedio/vector-search-analogy.png', steps: [['Embed', 'Represent the query', 'An embedding model maps the query into a vector.'], ['Index', 'Prepare stored vectors', 'Documents or other items are embedded and stored for search.'], ['Compare', 'Find nearby vectors', 'The system searches for the closest candidates.'], ['Filter', 'Apply constraints', 'Metadata, access rules, and freshness limits remove invalid results.'], ['Rank', 'Return useful evidence', 'The application orders candidates for retrieval or generation.']], examples: [['Everyday example', 'Find a recipe', '“quick vegetarian dinner”', 'searches nearby recipe vectors', 'a ranked set of related recipes'], ['Business example', 'Support search', 'a customer issue in new wording', 'combines semantic similarity with product filters', 'relevant cases or policy passages']], not: [['Vector Search ≠ Keyword Search', 'Vector Search: compares learned numerical representations', 'Keyword Search: matches terms or text signals'], ['Vector Search ≠ Embedding', 'Vector Search: the search operation and index', 'Embedding: the vector representation used by that operation'], ['Vector Search ≠ RAG', 'Vector Search: one retrieval method', 'RAG: a larger pattern that retrieves evidence and generates an answer']], related: ['Documents', '↓', 'Embeddings', '↓', 'Vector index', '↓', 'Nearest-neighbor search', '↓', 'Retrieved candidates'], chips: [['Embeddings', 'embeddings.html'], ['RAG', 'rag.html'], ['Grounding', 'grounding.html'], ['Context Window', 'context-window.html']], remember: 'Vector search retrieves semantically nearby items; it is one component in a larger AI system.', video: ['vedio/vector-search.mp4', 'vedio/vector-search.png', '', 'A visual explanation of vector search.'] }),
  page({ file: 'grounding.html', section: '05 · Embeddings, RAG & Vector Search', topic: 'Grounding', number: '04', back: ['embeddings-rag-vector-search.html', 'Embeddings, RAG & Vector Search'], lede: 'Grounding connects an AI response to trusted evidence, data, or rules available for the current task.', definition: ['Grounding is the practice of giving an AI system reliable external information and requiring the result to stay supported by it.', 'The evidence may come from retrieved documents, a database, a tool, or a deterministic rule. Grounding can reduce unsupported answers, but it depends on source quality and correct use of the evidence.'], analogy: 'Think of it like a news writer working with a folder of source documents. The writer can draft a clear story, but the claims should remain traceable to the sources.', analogyImage: 'vedio/grounding-analogy.png', steps: [['Source', 'Choose trusted information', 'The system identifies data, documents, tools, or rules it can rely on.'], ['Retrieve', 'Bring relevant evidence', 'The current question selects the information needed for the task.'], ['Constrain', 'Set evidence rules', 'Instructions define how to cite, abstain, or handle missing support.'], ['Generate', 'Produce a response', 'The model writes an answer using the supplied evidence.'], ['Verify', 'Check the claims', 'The system or a reviewer checks support, freshness, and permissions.']], examples: [['Everyday example', 'Product question', '“Does this ticket include a checked bag?”', 'uses the current booking record and fare rules', 'an answer tied to the record'], ['Business example', 'Policy assistant', 'a compliance question', 'retrieves approved policy sources', 'a cited answer or escalation']], not: [['Grounding ≠ Fine-tuning', 'Grounding: supplies evidence at task time', 'Fine-tuning: changes model parameters through training'], ['Grounding ≠ Citation Only', 'Grounding: constrains the answer with usable evidence', 'Citation only: may add a link without checking whether the claim is supported'], ['Grounding ≠ Guaranteed Accuracy', 'Grounding: improves the evidence connection', 'Accuracy: still depends on source, retrieval, interpretation, and validation']], related: ['Trusted source', '↓', 'Retrieval or tool', '↓', 'Evidence in context', '↓', 'Supported answer'], chips: [['RAG', 'rag.html'], ['Embeddings', 'embeddings.html'], ['Vector Search', 'vector-search.html'], ['Structured Outputs', 'structured-outputs.html']], remember: 'Grounding keeps an AI response connected to trusted evidence for the current task.', video: ['vedio/grounding.mp4', 'vedio/grounding.png', '', 'A visual explanation of grounding.'] }),

  page({ file: 'ai-agent.html', section: '06 · Agents, Tools & MCP', topic: 'AI Agent', number: '01', back: ['ai-knowledge.html#agents', 'Agents, Tools & MCP'], lede: 'An AI agent is a system that uses a model, instructions, tools, and a control loop to work toward a goal.', definition: ['An AI agent is a software system that can decide what step to take next while working toward a goal.', 'A typical agent combines a model with instructions, tools, state or memory, permissions, and stopping conditions. The model helps select or explain actions; surrounding software controls what can actually happen.'], analogy: 'Think of it like giving an AI worker a goal and a toolbox. The worker can choose a tool, inspect the result, and continue, but the toolbox and permissions define the safe boundary.', analogyImage: 'vedio/ai-agent.png', steps: [['Goal', 'Receive the objective', 'The system gets a task, constraints, and success condition.'], ['Plan', 'Choose the next step', 'The model proposes a response, question, or tool call.'], ['Act', 'Use an allowed tool', 'The application validates and executes the selected action.'], ['Observe', 'Read the result', 'The tool result becomes new context for the next decision.'], ['Stop', 'Finish or escalate', 'The loop ends when the goal is met, blocked, or unsafe.']], examples: [['Everyday example', 'Travel planning', 'a request to compare train options', 'searches schedules and checks constraints', 'a plan with links and trade-offs'], ['Business example', 'Document workflow', 'a request to process an invoice', 'reads the document, checks fields, and routes exceptions', 'a completed record or human review']], not: [['Agent ≠ LLM', 'LLM: the reasoning and language model', 'Agent: a system using models, tools, instructions, and a control loop'], ['Agent ≠ Chatbot', 'Chatbot: primarily communicates with a person', 'Agent: can take actions and use tools toward a goal'], ['Agent ≠ Workflow', 'Workflow: usually follows predefined steps', 'Agent: can dynamically choose the next action within limits']], related: ['Goal', '+', 'Model', '+', 'Instructions', '+', 'Tools', '+', 'Agent Loop', '=', 'AI Agent'], chips: [['Tool Calling', 'tool-calling.html'], ['Agent Loop', 'agent-loop.html'], ['LLM', 'llm.html'], ['Failure Handling', 'failure-handling.html']], remember: 'An AI agent combines a model with tools and a control loop so it can take actions toward a goal.', video: ['vedio/ai-agent.mp4', 'vedio/ai-agent.png', '', 'A visual explanation of AI agents.'] }),
  page({ file: 'tool-calling.html', section: '06 · Agents, Tools & MCP', topic: 'Tool Calling', number: '02', back: ['ai-knowledge.html#agents', 'Agents, Tools & MCP'], lede: 'Tool calling lets a model request a defined function, API, database query, or other external action.', definition: ['Tool calling is the pattern where a model selects a named tool and produces arguments for an application to execute.', 'The model does not automatically gain the tool’s permissions. The application should validate the arguments, enforce access, execute the action, and return the result to the model or user.'], analogy: 'Think of it like an assistant deciding when to use a calculator, browser, database, or another tool. The assistant can request the tool, but the tool still follows its own rules.', analogyImage: 'vedio/tool-calling.png', steps: [['Describe', 'Register the tool', 'The application defines the name, purpose, inputs, and limits.'], ['Choose', 'Select a tool', 'The model decides whether a tool is useful for the current task.'], ['Validate', 'Check arguments and permission', 'Trusted code verifies the request before execution.'], ['Execute', 'Run the tool', 'The external system returns data or performs an allowed action.'], ['Continue', 'Use the result', 'The model or workflow turns the result into the next step.']], examples: [['Everyday example', 'Calculator', '“What is 18% of 240?”', 'requests a calculator tool', 'the calculated value'], ['Business example', 'Order lookup', 'a customer asks for delivery status', 'calls an order API after permission checks', 'the current status or a handoff']], not: [['Tool Calling ≠ Function Execution', 'Tool Calling: a model requests an action with arguments', 'Function execution: application code validates and runs it'], ['Tool Calling ≠ Agent', 'Tool Calling: one connection pattern between a model and a tool', 'Agent: a broader system with goals and a loop'], ['Tool Calling ≠ Permission', 'Tool Calling: describes a possible action', 'Permission: controls whether the action is allowed']], related: ['Model', '↓', 'Tool schema', '↓', 'Validated call', '↓', 'Tool result', '↓', 'Next response'], chips: [['AI Agent', 'ai-agent.html'], ['Agent Loop', 'agent-loop.html'], ['System Prompt', 'system-prompts.html'], ['MCP', '']], remember: 'Tool calling lets a model request an action; trusted application code must validate and execute it.', video: ['vedio/tool-calling.mp4', 'vedio/tool-calling.png', '', 'A visual explanation of tool calling.'] }),
  page({ file: 'agent-loop.html', section: '06 · Agents, Tools & MCP', topic: 'Agent Loop', number: '03', back: ['ai-knowledge.html#agents', 'Agents, Tools & MCP'], lede: 'An agent loop repeats decision, action, observation, and stopping checks until a task is complete or blocked.', definition: ['An agent loop is the control cycle that lets an agent continue working after each model or tool result.', 'The loop normally has a goal, a model decision, optional tool execution, an observation, and a stopping condition. Limits on time, steps, cost, and permissions keep the loop bounded.'], analogy: 'Think of it like a person following a checklist that can change after every result. They look at the latest information, choose the next step, and stop when the job is done or a supervisor is needed.', analogyImage: 'vedio/agent-loop.png', steps: [['Goal', 'State the task', 'The loop starts with an objective and constraints.'], ['Decide', 'Choose the next action', 'The model proposes an answer, question, or tool call.'], ['Act', 'Execute an allowed step', 'The application validates and performs the action.'], ['Observe', 'Read the new state', 'The result is added to the working context.'], ['Stop or repeat', 'Check the boundary', 'The loop finishes or continues under step, time, and risk limits.']], examples: [['Everyday example', 'Plan a route', 'a destination and travel time', 'checks a route, sees a delay, and searches another', 'an updated route or a question'], ['Business example', 'Ticket triage', 'a support issue', 'looks up an account, checks policy, and routes the case', 'a response or escalation']], not: [['Agent Loop ≠ One Prompt', 'Agent Loop: multiple decisions and observations over time', 'One prompt: one model request with no required control cycle'], ['Agent Loop ≠ Workflow', 'Agent Loop: can choose the next step dynamically', 'Workflow: usually follows predefined transitions'], ['Agent Loop ≠ Infinite Autonomy', 'Agent Loop: must have stopping and permission limits', 'Unbounded autonomy: unsafe behavior without a controlled boundary']], related: ['Goal', '↓', 'Decide', '↓', 'Tool or response', '↓', 'Observe', '↺ continue or stop'], chips: [['AI Agent', 'ai-agent.html'], ['Tool Calling', 'tool-calling.html'], ['Failure Handling', 'failure-handling.html'], ['Functional Tests', 'functional-tests.html']], remember: 'An agent loop turns a model decision into a bounded sequence of actions and observations.', video: ['vedio/agent-loop.mp4', 'vedio/agent-loop.png', '', 'A visual explanation of the agent loop.'] }),

  page({ file: 'ollama.html', section: '07 · Model Serving & Local AI', topic: 'Ollama', number: '01', back: ['model-serving-local-ai.html', 'Model Serving & Local AI'], lede: 'Ollama is software for running and managing AI models locally.', definition: ['Ollama is a local model runtime and management tool.', 'It helps download, configure, start, and interact with supported models on a local machine. Ollama is not the language model itself; it is the software layer that runs and manages models.'], analogy: 'Think of it like a local model launcher and manager. It helps you install and run the engine, but the engine—the model weights—are a separate thing.', steps: [['Choose', 'Select a model', 'A user or application chooses a compatible local model.'], ['Prepare', 'Download and configure it', 'The runtime obtains model files and runtime settings.'], ['Run', 'Start a local service', 'Ollama loads the model and exposes a local interface.'], ['Request', 'Send a prompt or API call', 'An application uses the local endpoint to generate a result.']], examples: [['Everyday example', 'Private notes', 'a short note on a laptop', 'a local model processes the prompt without a hosted request', 'a summary or rewrite'], ['AI product example', 'Local prototype', 'a prompt from a test app', 'Ollama serves a selected model over a local API', 'a response for development']], not: [['Ollama ≠ LLM', 'Ollama: runs and manages models', 'LLM: the actual language model'], ['Ollama ≠ Cloud AI service', 'Ollama: software running on a local machine', 'Cloud service: remote infrastructure accessed over a network'], ['Ollama ≠ Privacy Guarantee', 'Ollama: can keep a request local when configured that way', 'Privacy: also depends on logs, files, network, and the surrounding application']], related: ['Local machine', '↓', 'Ollama runtime', '↓', 'Model files', '↓', 'Local API', '↓', 'Application'], chips: [['Quantization', 'quantization.html'], ['Runtime Constraints', 'runtime-constraints.html'], ['LLM', 'llm.html'], ['Model Serving', 'model-serving-local-ai.html']], remember: 'Ollama is software for running and managing AI models locally; it is not the model itself.', video: ['vedio/ollama.mp4', 'vedio/ollama.png', 'vedio/ollama.vtt', 'A visual explanation of Ollama.'] }),
  page({ file: 'quantization.html', section: '07 · Model Serving & Local AI', topic: 'Quantization', number: '02', back: ['model-serving-local-ai.html', 'Model Serving & Local AI'], lede: 'Quantization stores model values with lower numerical precision to reduce memory or improve runtime efficiency.', definition: ['Quantization converts numerical values into a lower-precision representation.', 'For model serving, this can reduce file size and memory use and may improve speed. The trade-off is that lower precision can change model behavior or quality, so the chosen format must be evaluated for the target task.'], analogy: 'Think of it like compressing a large model so it takes less memory while trying to preserve most of its ability. The smaller package can be easier to carry, but some detail may be lost.', steps: [['Start', 'Load model values', 'The original model contains numerical weights at a chosen precision.'], ['Convert', 'Map to lower precision', 'Weights are represented with fewer bits or a more compact format.'], ['Run', 'Load the quantized model', 'The runtime uses the smaller representation for inference.'], ['Evaluate', 'Measure the trade-off', 'Teams compare quality, memory, speed, and task failures.']], examples: [['Everyday example', 'Laptop assistant', 'a quantized local model', 'uses less memory during a short chat', 'a response on hardware that could not load the full model'], ['Business example', 'Edge deployment', 'a target device with limited RAM', 'chooses a quantization level after testing', 'a workable local inference service']], not: [['Quantization ≠ Any Model Compression', 'Quantization: reduces numerical precision of values', 'Other compression: may prune, distill, or encode the model in different ways'], ['Quantization ≠ Free Speed', 'Quantization: a memory and numeric representation choice', 'Speed: depends on hardware kernels, runtime, batch, and workload'], ['Quantization ≠ No Quality Change', 'Quantization: aims to preserve useful behavior with fewer bits', 'Quality: must be measured because some tasks can degrade']], related: ['Full-precision model', '↓', 'Lower-precision weights', '↓', 'Smaller memory footprint', '↓', 'Local inference'], chips: [['Ollama', 'ollama.html'], ['Runtime Constraints', 'runtime-constraints.html'], ['Parameters', 'parameters.html'], ['Tokens per Second', 'tokens-per-second.html']], remember: 'Quantization trades numerical precision for a smaller and often easier-to-run model.', video: ['vedio/quantization.mp4', 'vedio/quantization.png', 'vedio/quantization.vtt', 'A visual explanation of quantization.'] }),
  page({ file: 'runtime-constraints.html', section: '07 · Model Serving & Local AI', topic: 'Runtime Constraints', number: '03', back: ['model-serving-local-ai.html', 'Model Serving & Local AI'], lede: 'Runtime constraints are the hardware, software, time, memory, and policy limits that shape how an AI system can run.', definition: ['Runtime constraints are the practical limits around an AI workload while it is running.', 'They include memory, compute, context length, latency, throughput, concurrency, network access, thermal limits, permissions, and failure behavior. A model that works in isolation may still fail inside a real workflow.'], analogy: 'Think of it like fitting a kitchen into a small apartment. The recipe may be possible, but counter space, power, time, and access determine what can actually happen.', steps: [['Target', 'Define the workload', 'Name the model, input size, output size, users, and success criteria.'], ['Measure', 'Check the environment', 'Measure memory, latency, throughput, concurrency, and network conditions.'], ['Fit', 'Choose a workable configuration', 'Adjust model, quantization, context, batching, or fallback behavior.'], ['Operate', 'Monitor real use', 'Watch resource use, errors, queueing, and quality over time.']], examples: [['Everyday example', 'Laptop chat', 'a long prompt on a 24GB laptop', 'context and model memory compete for available RAM', 'a slower response or a need to shorten context'], ['Business example', 'Shared service', 'many simultaneous requests', 'capacity and queue limits affect response time', 'a service that scales or routes to a fallback']], not: [['Runtime Constraints ≠ Model Capability', 'Runtime Constraints: limits of the environment and workload', 'Model Capability: what the model can do under suitable conditions'], ['Runtime Constraints ≠ Latency Only', 'Runtime Constraints: memory, time, throughput, access, and more', 'Latency: one timing measure'], ['Runtime Constraints ≠ One Hardware Number', 'Runtime Constraints: a set of interacting limits', 'A hardware specification: one property that may not predict end-to-end behavior']], related: ['Model', '+', 'Hardware', '+', 'Runtime', '+', 'Workload', '=', 'Usable system'], chips: [['Ollama', 'ollama.html'], ['Quantization', 'quantization.html'], ['Latency', 'latency.html'], ['Tokens per Second', 'tokens-per-second.html']], remember: 'A model is usable only when it fits the runtime limits of the real workload.', video: ['vedio/runtime-constraints.mp4', 'vedio/runtime-constraints.png', 'vedio/runtime-constraints.vtt', 'A visual explanation of runtime constraints.'] }),

  page({ file: 'functional-tests.html', section: '08 · Evaluation & Reliability', topic: 'Functional Tests', number: '01', back: ['evaluation.html', 'Evaluation & Reliability'], lede: 'Functional tests check whether an AI system performs the task it is supposed to perform.', definition: ['A functional test checks whether an AI workflow produces an acceptable result for a defined input and task.', 'For AI systems, the test may check extracted fields, tool arguments, citations, routing, output schema, or a human-review decision. Tests should use representative cases, not only easy examples.'], analogy: 'Think of it like testing a vending machine with normal coins, a rejected coin, and an empty slot. You check the expected result and the safe response for each case.', steps: [['Define', 'State the expected behavior', 'Write what success and safe failure look like for the task.'], ['Prepare', 'Create representative cases', 'Include normal, ambiguous, empty, long, and adversarial inputs.'], ['Run', 'Execute the workflow', 'Measure the model, tools, validators, and handoffs together.'], ['Review', 'Compare against expectations', 'Record failures, regressions, and cases needing human judgment.']], examples: [['Everyday example', 'Calendar extraction', '“Lunch with Mei at 2pm Friday”', 'extracts title, person, date, and time', 'a valid event or a clarification'], ['Business example', 'Invoice pipeline', 'an invoice with an unusual total', 'extracts fields and flags the exception', 'structured data plus review routing']], not: [['Functional Tests ≠ Model Benchmark', 'Functional Tests: check an end-to-end task behavior', 'Model Benchmark: compares model capability on a defined benchmark'], ['Functional Tests ≠ One Happy Path', 'Functional Tests: include representative and failure cases', 'Happy path: one normal example'], ['Functional Tests ≠ Evaluation Only Once', 'Functional Tests: can run in CI and regression checks', 'One-time review: can miss later changes']], related: ['Task definition', '↓', 'Test cases', '↓', 'AI workflow', '↓', 'Expected result', '↓', 'Regression record'], chips: [['Failure Modes', 'failure-modes.html'], ['Deployment Readiness', 'deployment-readiness.html'], ['Structured Outputs', 'structured-outputs.html'], ['Failure Handling', 'failure-handling.html']], remember: 'Functional tests check the complete AI workflow against representative expected behavior.', video: ['vedio/functional-tests.mp4', 'vedio/functional-tests.png', '', 'A visual explanation of functional testing.'] }),
  page({ file: 'failure-modes.html', section: '08 · Evaluation & Reliability', topic: 'Failure Modes', number: '02', back: ['evaluation.html', 'Evaluation & Reliability'], lede: 'Failure modes are the recurring ways an AI system can produce an incorrect, unsafe, incomplete, or unusable result.', definition: ['A failure mode is a recognizable way a system can fail under a certain input, condition, or interaction.', 'Cataloging failure modes helps teams design tests, monitoring, recovery, and human review. It also separates model errors from retrieval, tool, integration, data, and workflow errors.'], analogy: 'Think of it like a pre-flight checklist. Naming the ways a journey can go wrong helps the crew notice risk before the same problem appears in production.', steps: [['Observe', 'Collect real failures', 'Capture examples from tests, pilots, logs, and user reports.'], ['Classify', 'Name the failure pattern', 'Separate hallucination, missing evidence, tool error, timeout, and other causes.'], ['Prioritize', 'Estimate impact and frequency', 'Focus controls on failures that matter most.'], ['Control', 'Add a response', 'Use validation, fallback, monitoring, or human review.']], examples: [['Everyday example', 'Wrong date', '“Book Friday” across time zones', 'interprets the date without clarifying', 'an incorrect event or clarification need'], ['Business example', 'Unsupported policy answer', 'a question outside retrieved sources', 'generates a confident answer anyway', 'a false claim instead of a handoff']], not: [['Failure Modes ≠ Random Bugs', 'Failure Modes: recurring patterns with a cause or condition', 'Random bug: an isolated defect that may need a different fix'], ['Failure Modes ≠ Model Errors Only', 'Failure Modes: include integration, data, tool, and workflow failures', 'Model error: one possible source'], ['Failure Modes ≠ Test Cases', 'Failure Modes: describe how the system can fail', 'Test cases: inputs used to reveal or guard against those failures']], related: ['Input', '↓', 'Failure condition', '↓', 'Observed failure mode', '↓', 'Control + test + monitor'], chips: [['Functional Tests', 'functional-tests.html'], ['Failure Handling', 'failure-handling.html'], ['Deployment Readiness', 'deployment-readiness.html'], ['Runtime Constraints', 'runtime-constraints.html']], remember: 'Naming recurring failure modes makes them testable and controllable.', video: ['vedio/failure-modes.mp4', 'vedio/failure-modes.png', '', 'A visual explanation of AI failure modes.'] }),
  page({ file: 'deployment-readiness.html', section: '08 · Evaluation & Reliability', topic: 'Deployment Readiness', number: '03', back: ['evaluation.html', 'Evaluation & Reliability'], lede: 'Deployment readiness is the evidence-based judgment that an AI system is safe and useful enough for its intended release.', definition: ['Deployment readiness is a decision based on whether an AI system meets defined quality, reliability, safety, operational, and workflow requirements.', 'Readiness is not a single model score. It includes tested behavior, known failure modes, monitoring, recovery, ownership, permissions, cost, and a fallback when the system cannot complete a task.'], analogy: 'Think of it like opening a restaurant after a test service. The menu may work, but the team also needs safe food handling, staff roles, supply plans, and a response to problems.', steps: [['Define', 'Set release criteria', 'Name the quality, safety, latency, cost, and workflow requirements.'], ['Test', 'Run representative scenarios', 'Exercise normal use, edge cases, failures, and recovery paths.'], ['Operate', 'Prepare ownership and monitoring', 'Decide who watches the system and what signals trigger action.'], ['Decide', 'Release, limit, or stop', 'Use the evidence to choose scope, safeguards, and rollout plan.']], examples: [['Everyday example', 'Personal assistant', 'a reminder workflow', 'passes valid input and handles missing details', 'a limited release with a clear fallback'], ['Business example', 'Document processing', 'a tested invoice workflow', 'meets accuracy, latency, audit, and review requirements', 'a controlled production rollout']], not: [['Deployment Readiness ≠ Model Quality', 'Deployment Readiness: an end-to-end release decision', 'Model Quality: one dimension of system behavior'], ['Deployment Readiness ≠ Production Launch', 'Deployment Readiness: evidence and decision before or during release', 'Production Launch: the act of making the system available'], ['Deployment Readiness ≠ Zero Risk', 'Deployment Readiness: known risks have controls and owners', 'Zero Risk: an unrealistic guarantee for changing systems']], related: ['Functional tests', '+', 'Failure modes', '+', 'Operations', '+', 'Human ownership', '=', 'Release decision'], chips: [['Functional Tests', 'functional-tests.html'], ['Failure Modes', 'failure-modes.html'], ['Failure Handling', 'failure-handling.html'], ['Runtime Constraints', 'runtime-constraints.html']], remember: 'Deployment readiness is an evidence-based decision about the whole AI workflow, not just the model.', video: ['vedio/deployment-readiness.mp4', 'vedio/deployment-readiness.png', '', 'A visual explanation of deployment readiness.'] })
];

const renderSteps = (items) => items.map(([label, title, text], index) => `<div class="step-card"><strong>${index + 1} · ${esc(label)}</strong><b>${esc(title)}</b><span class="muted">${esc(text)}</span></div>`).join('');
const renderExamples = (items) => items.map(([kind, title, input, system, output]) => `<div><h3>${esc(kind)} · ${esc(title)}</h3><p><b>Input:</b> ${esc(input)}</p><p><b>AI / System:</b> ${esc(system)}</p><p><b>Output:</b> ${esc(output)}</p></div>`).join('');
const renderMisconceptions = (items) => items.map(([title, left, right]) => `<div class="misconception-card"><h3>${esc(title)}</h3><p>${esc(left)}</p><p>${esc(right)}</p></div>`).join('');
const renderMap = (items) => `<div class="concept-tree">${items.map(esc).join('\n')}</div>`;
const renderChips = (items) => items.map(([label, href]) => href ? `<a class="chip" href="${esc(href)}">${esc(label)}</a>` : `<span class="chip">${esc(label)}</span>`).join('');

const renderPage = (data) => {
  const [backHref, backLabel] = data.back;
  const [videoSrc, poster, track, videoCaption] = data.video;
  const pluralTopics = new Set(['Foundation Models', 'Parameters', 'Structured Outputs', 'Embeddings', 'Functional Tests', 'Failure Modes', 'Runtime Constraints', 'Tokens per Second']);
  const question = data.topic === 'AI Agent' ? 'What is an AI Agent?' : pluralTopics.has(data.topic) ? `What are ${data.topic}?` : `What is ${data.topic === 'LLM' ? 'an LLM' : data.topic === 'KV Cache' ? 'a KV Cache' : data.topic}?`;
  const analogyImage = data.analogyImage ? `<figure><img src="${esc(data.analogyImage)}" alt="${esc(data.topic)} analogy illustration"><figcaption>A visual analogy for ${esc(data.topic)}.</figcaption></figure>` : '';
  const trackMarkup = track ? `<track kind="captions" src="${esc(track)}" srclang="en" label="English captions" default>` : '';
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(data.topic)} · ${esc(data.section)}</title><meta name="description" content="${esc(data.lede)}"><link rel="stylesheet" href="topic.css?v=20260907"><link rel="stylesheet" href="site-directory.css"><script defer src="site-directory.js"></script></head>
<body id="top" class="standard-topic"><nav><div class="wrap"><a class="brand" href="ai-knowledge.html">Rebecca <span>Forward-Deployed AI</span></a></div></nav>
<main class="wrap topic-main"><a class="back" href="${esc(backHref)}">← ${esc(backLabel)}</a><div class="eyebrow">${esc(data.section)} · Topic ${esc(data.number)}</div><h1>${esc(question)}</h1><p class="lede">${esc(data.lede)}</p>
<nav class="on-page" aria-label="On this page"><b>On this page</b><a href="#definition">What is it?</a><a href="#analogy">Think of it like...</a><a href="#process">How it works</a><a href="#examples">Real-world examples</a><a href="#not">What it is NOT</a><a href="#related">Related concepts</a><a href="#remember">Remember this</a><a href="#video">Video</a></nav>
<section class="grid">
<article id="definition" class="card wide topic-definition"><h2>What is it?</h2><p class="definition">${esc(data.definition[0])}</p><p class="muted">${esc(data.definition[1])}</p></article>
<article id="analogy" class="card wide topic-analogy"><h2>Think of it like...</h2><div class="analogy-box${data.analogyImage ? '' : ' text-only'}"><p>${esc(data.analogy)}</p>${analogyImage}</div></article>
<article id="process" class="card wide topic-process"><h2>How it works</h2><div class="process-flow">${renderSteps(data.steps)}</div></article>
<article id="examples" class="card wide topic-example"><h2>Real-world examples</h2><div class="example-grid">${renderExamples(data.examples)}</div></article>
<article id="not" class="card wide topic-comparison"><h2>What it is NOT</h2><div class="misconceptions">${renderMisconceptions(data.not)}</div></article>
<article id="related" class="card wide topic-related"><h2>Related concepts</h2>${renderMap(data.related)}<p class="muted">Explore next</p><div class="chips">${renderChips(data.chips)}</div></article>
<article id="remember" class="card wide topic-takeaway"><h2>Remember this</h2><p class="note">${esc(data.remember)}</p></article>
<article id="video" class="card wide video-card"><div class="video-label"><div><div class="eyebrow">Independent explainer</div><h2>Video</h2></div><small>visual explainer${track ? ' · captions included' : ''}</small></div><video controls preload="metadata" poster="${esc(poster)}" aria-label="${esc(data.topic)} explainer video"><source src="${esc(videoSrc)}" type="video/mp4">${trackMarkup}Your browser does not support video playback.</video><p class="video-caption">${esc(videoCaption)}</p></article>
</section></main><a class="back-to-top" href="#top" aria-label="Back to top">↑</a></body></html>
`;
};

for (const data of pages) writeFileSync(join(root, data.file), renderPage(data), 'utf8');
console.log(`Generated ${pages.length} concept detail pages.`);
